/**
 * Booking link URL helpers for the studio booking-link hub.
 *
 * Provides structured public booking URLs for a given studio:
 * - Studio root: /book/{studioSlug}
 * - Per-artist: /book/{studioSlug}/artist/{artistSlug}
 * - Per-service: /book/{studioSlug}/service/{serviceId}
 * - Flash events: /book/{studioSlug}/flash/{eventId}
 */

import { slugify } from '@/lib/utils'

export interface ArtistLinkInfo {
  id: string
  displayName: string
  avatarUrl: string | null
  slug: string
  url: string
}

export interface ServiceLinkInfo {
  id: string
  name: string
  url: string
}

export interface FlashEventLinkInfo {
  id: string
  title: string
  eventDate: string
  url: string
}

export interface StudioBookingUrls {
  studioUrl: string
  studioSlug: string
  artistLinks: ArtistLinkInfo[]
  serviceLinks: ServiceLinkInfo[]
  flashEventLinks: FlashEventLinkInfo[]
}

/**
 * Reads NEXT_PUBLIC_APP_URL from env or falls back to window.location.origin on client.
 */
export function getPublicOrigin(): string {
  if (typeof process !== 'undefined' && process.env.NEXT_PUBLIC_APP_URL) {
    return process.env.NEXT_PUBLIC_APP_URL.replace(/\/$/, '')
  }
  if (typeof window !== 'undefined') {
    return window.location.origin
  }
  return 'https://inkos.app'
}

/**
 * Derives a URL-safe artist slug from display_name.
 * Uses the artist's stored slug if available (once the migration lands),
 * otherwise falls back to slugify(displayName).
 */
export function artistSlugFrom(displayName: string): string {
  return slugify(displayName)
}

export interface RawArtist {
  id: string
  display_name: string
  avatar_url: string | null
}

export interface RawService {
  id: string
  name: string
}

export interface RawFlashEvent {
  id: string
  title: string
  event_date: string
}

export function buildStudioBookingUrls(
  studioSlug: string,
  artists: RawArtist[],
  services: RawService[],
  flashEvents: RawFlashEvent[],
): StudioBookingUrls {
  const origin = getPublicOrigin()
  const base = `${origin}/book/${studioSlug}`

  const artistLinks: ArtistLinkInfo[] = artists.map((a) => {
    const slug = artistSlugFrom(a.display_name)
    return {
      id: a.id,
      displayName: a.display_name,
      avatarUrl: a.avatar_url,
      slug,
      url: `${base}/artist/${slug}`,
    }
  })

  const serviceLinks: ServiceLinkInfo[] = services.map((s) => ({
    id: s.id,
    name: s.name,
    url: `${base}/service/${s.id}`,
  }))

  const flashEventLinks: FlashEventLinkInfo[] = flashEvents.map((e) => ({
    id: e.id,
    title: e.title,
    eventDate: e.event_date,
    url: `${base}/flash/${e.id}`,
  }))

  return {
    studioUrl: base,
    studioSlug,
    artistLinks,
    serviceLinks,
    flashEventLinks,
  }
}

/**
 * GET /api/booking-links
 *
 * Returns all public booking URLs for the authenticated studio:
 * studio root, per-artist, per-service, and upcoming flash events.
 */
import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { buildStudioBookingUrls } from '@/lib/booking-links/urls'
import { logger } from '@/lib/logger'

export async function GET(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  try {
    const supabase = await createClient()
    const studioId = authUser.studioId

    const [studioResult, artistsResult, servicesResult] = await Promise.all([
      supabase
        .from('studios')
        .select('slug')
        .eq('id', studioId)
        .single(),
      supabase
        .from('artists')
        .select('id, display_name, avatar_url')
        .eq('studio_id', studioId)
        .eq('status', 'active')
        .order('sort_order', { ascending: true }),
      supabase
        .from('services')
        .select('id, name')
        .eq('studio_id', studioId)
        .eq('is_active', true)
        .order('sort_order', { ascending: true }),
    ])

    if (studioResult.error || !studioResult.data) {
      logger.error({ err: studioResult.error, studioId }, 'booking-links: studio lookup failed')
      return NextResponse.json({ error: 'Studio not found' }, { status: 404 })
    }

    const studioSlug = studioResult.data.slug
    const artists = artistsResult.data ?? []
    const services = servicesResult.data ?? []

    // Flash events are from Sprint 4A — table may not exist yet. Silently skip if absent.
    let flashEvents: Array<{ id: string; title: string; event_date: string }> = []
    try {
      const flashResult = await supabase
        .from('flash_events' as 'services') // type cast avoids missing-table TS error
        .select('id, title, event_date')
        .eq('studio_id', studioId)
        .eq('public', true)
        .gte('event_date', new Date().toISOString().split('T')[0])
        .order('event_date', { ascending: true })
        .limit(10)

      if (!flashResult.error && flashResult.data) {
        flashEvents = (flashResult.data as Array<{ id: string; title: string; event_date: string }>)
      }
    } catch {
      // Flash events table may not be migrated yet — skip gracefully
    }

    const urls = buildStudioBookingUrls(studioSlug, artists, services, flashEvents)
    return NextResponse.json({ data: urls })
  } catch (err) {
    logger.error({ err }, 'booking-links GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

'use client'

/**
 * QrCodeCard — generates and displays a QR code for a given URL.
 *
 * Uses the `qrcode` npm library on the client side:
 * - Renders as inline SVG (instant, no server round-trip)
 * - Download as SVG or PNG (256/512/1024)
 * - Optional: white or brand-color background
 */
import { useState, useEffect, useCallback, useRef } from 'react'
import QRCode from 'qrcode'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'
import { Download, Loader2 } from 'lucide-react'
import { toast } from 'sonner'
import { logger } from '@/lib/logger'

type QrSize = 256 | 512 | 1024
type QrBackground = 'white' | 'brand'

interface QrCodeCardProps {
  url: string
  label?: string
  brandColor?: string | null
  className?: string
}

const SIZE_OPTIONS: QrSize[] = [256, 512, 1024]

export function QrCodeCard({ url, label, brandColor, className }: QrCodeCardProps) {
  const [svgString, setSvgString] = useState<string>('')
  const [background, setBackground] = useState<QrBackground>('white')
  const [downloadSize, setDownloadSize] = useState<QrSize>(512)
  const [isGenerating, setIsGenerating] = useState(false)
  const svgContainerRef = useRef<HTMLDivElement>(null)

  const bgColor = background === 'brand' && brandColor ? brandColor : '#ffffff'

  // Generate SVG whenever url or background changes
  useEffect(() => {
    if (!url) return
    let cancelled = false

    void (async () => {
      try {
        const svg = await QRCode.toString(url, {
          type: 'svg',
          margin: 2,
          color: {
            dark: '#1a1a1a',
            light: bgColor,
          },
          errorCorrectionLevel: 'M',
        })
        if (!cancelled) setSvgString(svg)
      } catch (err) {
        logger.error({ err, url }, 'QrCodeCard: SVG generation failed')
      }
    })()

    return () => { cancelled = true }
  }, [url, bgColor])

  const downloadSvg = useCallback(() => {
    if (!svgString) return
    const blob = new Blob([svgString], { type: 'image/svg+xml' })
    const link = document.createElement('a')
    link.href = URL.createObjectURL(blob)
    link.download = `booking-qr-${downloadSize}.svg`
    link.click()
    URL.revokeObjectURL(link.href)
    toast.success('QR code SVG downloaded')
  }, [svgString, downloadSize])

  const downloadPng = useCallback(async () => {
    if (!url) return
    setIsGenerating(true)
    try {
      const dataUrl = await QRCode.toDataURL(url, {
        type: 'image/png',
        width: downloadSize,
        margin: 2,
        color: {
          dark: '#1a1a1a',
          light: bgColor,
        },
        errorCorrectionLevel: 'M',
      })
      const link = document.createElement('a')
      link.href = dataUrl
      link.download = `booking-qr-${downloadSize}.png`
      link.click()
      toast.success(`QR code PNG (${downloadSize}×${downloadSize}) downloaded`)
    } catch (err) {
      logger.error({ err, url }, 'QrCodeCard: PNG download failed')
      toast.error('Failed to generate PNG')
    } finally {
      setIsGenerating(false)
    }
  }, [url, downloadSize, bgColor])

  return (
    <div className={cn('rounded-xl border border-border/60 bg-card p-4 space-y-4', className)}>
      {label && (
        <p className="text-xs font-medium text-muted-foreground uppercase tracking-wide">{label}</p>
      )}

      {/* QR preview */}
      <div
        ref={svgContainerRef}
        className="flex items-center justify-center rounded-lg overflow-hidden border border-border/40"
        style={{ background: bgColor, minHeight: 160 }}
        aria-label={`QR code for ${url}`}
      >
        {svgString ? (
          <div
            className="w-40 h-40"
            // eslint-disable-next-line react/no-danger
            dangerouslySetInnerHTML={{ __html: svgString }}
          />
        ) : (
          <div className="flex items-center justify-center w-40 h-40">
            <Loader2 className="h-6 w-6 animate-spin text-muted-foreground/40" />
          </div>
        )}
      </div>

      {/* Background toggle */}
      {brandColor && (
        <div className="flex items-center gap-2">
          <span className="text-xs text-muted-foreground">Background:</span>
          <div className="flex gap-1">
            {(['white', 'brand'] as QrBackground[]).map((bg) => (
              <button
                key={bg}
                type="button"
                onClick={() => setBackground(bg)}
                className={cn(
                  'px-2.5 py-1 rounded text-xs font-medium border transition-colors',
                  background === bg
                    ? 'bg-foreground text-background border-foreground'
                    : 'border-border/60 text-muted-foreground hover:border-border'
                )}
              >
                {bg === 'white' ? 'White' : 'Brand color'}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Size selector */}
      <div className="flex items-center gap-2">
        <span className="text-xs text-muted-foreground">Size:</span>
        <div className="flex gap-1">
          {SIZE_OPTIONS.map((size) => (
            <button
              key={size}
              type="button"
              onClick={() => setDownloadSize(size)}
              className={cn(
                'px-2.5 py-1 rounded text-xs font-medium border transition-colors',
                downloadSize === size
                  ? 'bg-foreground text-background border-foreground'
                  : 'border-border/60 text-muted-foreground hover:border-border'
              )}
            >
              {size}
            </button>
          ))}
        </div>
      </div>

      {/* Download buttons */}
      <div className="flex gap-2">
        <Button
          variant="outline"
          size="sm"
          className="h-8 text-xs gap-1.5 flex-1"
          onClick={downloadSvg}
          disabled={!svgString}
        >
          <Download className="h-3 w-3" />
          SVG
        </Button>
        <Button
          variant="outline"
          size="sm"
          className="h-8 text-xs gap-1.5 flex-1"
          onClick={() => void downloadPng()}
          disabled={isGenerating || !url}
        >
          {isGenerating ? (
            <Loader2 className="h-3 w-3 animate-spin" />
          ) : (
            <Download className="h-3 w-3" />
          )}
          PNG {downloadSize}px
        </Button>
      </div>
    </div>
  )
}

'use client'

/**
 * SocialShareCard — social share presets for a booking URL.
 *
 * Surfaces:
 * - Copyable Instagram bio format
 * - Twitter intent share
 * - Facebook share
 * - WhatsApp deep-link (mobile)
 * - Email mailto
 * - Web Share API (on supported mobile browsers)
 */
import { useCallback } from 'react'
import { Button } from '@/components/ui/button'
import { toast } from 'sonner'
import {
  Copy,
  Mail,
  Share2,
  MessageCircle,
} from 'lucide-react'
import { cn } from '@/lib/utils'

interface SocialShareCardProps {
  url: string
  studioName?: string
  className?: string
}

// Simple branded share-button icon components using SVG paths
function TwitterXIcon({ className }: { className?: string }) {
  return (
    <svg className={className} viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
      <path d="M18.244 2.25h3.308l-7.227 8.26 8.502 11.24H16.17l-4.714-6.231-5.401 6.231H2.744l7.737-8.835L1.254 2.25H8.08l4.258 5.63L18.244 2.25zm-1.161 17.52h1.833L7.084 4.126H5.117z" />
    </svg>
  )
}

function FacebookIcon({ className }: { className?: string }) {
  return (
    <svg className={className} viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
      <path d="M24 12.073c0-6.627-5.373-12-12-12s-12 5.373-12 12c0 5.99 4.388 10.954 10.125 11.854v-8.385H7.078v-3.47h3.047V9.43c0-3.007 1.792-4.669 4.533-4.669 1.312 0 2.686.235 2.686.235v2.953H15.83c-1.491 0-1.956.925-1.956 1.874v2.25h3.328l-.532 3.47h-2.796v8.385C19.612 23.027 24 18.062 24 12.073z" />
    </svg>
  )
}

export function SocialShareCard({ url, studioName, className }: SocialShareCardProps) {
  const instagramText = `Book at: ${url}`
  const twitterText = studioName
    ? `Book your next tattoo session with ${studioName} 🖤`
    : 'Book your next tattoo session online'

  const copyToClipboard = useCallback(async (text: string, label: string) => {
    try {
      await navigator.clipboard.writeText(text)
      toast.success(`${label} copied`)
    } catch {
      toast.error('Copy failed — check browser permissions')
    }
  }, [])

  const handleWebShare = useCallback(async () => {
    if (!navigator.share) {
      await copyToClipboard(url, 'Link')
      return
    }
    try {
      await navigator.share({
        title: studioName ? `Book with ${studioName}` : 'Book online',
        text: twitterText,
        url,
      })
    } catch (err) {
      // User cancelled share — not an error
      if (err instanceof Error && err.name !== 'AbortError') {
        toast.error('Share failed')
      }
    }
  }, [url, studioName, twitterText, copyToClipboard])

  const socialLinks = [
    {
      label: 'Share on X',
      icon: <TwitterXIcon className="h-3.5 w-3.5" />,
      href: `https://twitter.com/intent/tweet?text=${encodeURIComponent(twitterText)}&url=${encodeURIComponent(url)}`,
    },
    {
      label: 'Share on Facebook',
      icon: <FacebookIcon className="h-3.5 w-3.5" />,
      href: `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(url)}`,
    },
    {
      label: 'WhatsApp',
      icon: <MessageCircle className="h-3.5 w-3.5" />,
      href: `https://wa.me/?text=${encodeURIComponent(`${twitterText} ${url}`)}`,
    },
    {
      label: 'Email',
      icon: <Mail className="h-3.5 w-3.5" />,
      href: `mailto:?subject=${encodeURIComponent(studioName ? `Book with ${studioName}` : 'Book online')}&body=${encodeURIComponent(`${twitterText}\n\n${url}`)}`,
    },
  ]

  return (
    <div className={cn('rounded-xl border border-border/60 bg-card p-4 space-y-4', className)}>
      <p className="text-xs font-medium text-muted-foreground uppercase tracking-wide">
        Share your link
      </p>

      {/* Instagram bio format */}
      <div className="space-y-1.5">
        <p className="text-xs text-muted-foreground">Instagram bio format</p>
        <div className="flex items-center gap-2 rounded-lg border border-border/60 bg-muted/30 px-3 py-2">
          <span className="flex-1 text-xs font-mono truncate text-foreground/80">
            {instagramText}
          </span>
          <button
            type="button"
            onClick={() => void copyToClipboard(instagramText, 'Instagram bio text')}
            className="shrink-0 text-muted-foreground hover:text-foreground transition-colors"
            aria-label="Copy Instagram bio text"
          >
            <Copy className="h-3.5 w-3.5" />
          </button>
        </div>
      </div>

      {/* Social share buttons */}
      <div className="grid grid-cols-2 gap-2">
        {socialLinks.map(({ label, icon, href }) => (
          <a
            key={label}
            href={href}
            target="_blank"
            rel="noopener noreferrer"
            className={cn(
              'flex items-center justify-center gap-1.5 rounded-lg border border-border/60',
              'px-3 py-2 text-xs font-medium text-muted-foreground',
              'hover:bg-muted/50 hover:text-foreground transition-colors'
            )}
            aria-label={label}
          >
            {icon}
            <span>{label}</span>
          </a>
        ))}
      </div>

      {/* Web Share API / copy fallback */}
      <Button
        variant="outline"
        size="sm"
        className="w-full h-8 text-xs gap-1.5"
        onClick={() => void handleWebShare()}
      >
        <Share2 className="h-3.5 w-3.5" />
        {typeof navigator !== 'undefined' && 'share' in navigator
          ? 'Share via device'
          : 'Copy link'}
      </Button>
    </div>
  )
}

'use client'

/**
 * BookingLinkHub — the full booking-link management UI.
 *
 * Sections:
 * 1. Hero card — studio root URL, copy, test-in-new-tab, mobile preview
 * 2. Per-artist links — table with avatar, name, URL, copy, QR download
 * 3. Per-service links — URL, copy
 * 4. Flash events — upcoming event links (if any)
 * 5. QR code generator for the studio root URL
 * 6. Social share presets
 */
import { useState, useCallback } from 'react'
import { useQuery } from '@tanstack/react-query'
import { Skeleton } from '@/components/ui/skeleton'
import { Button } from '@/components/ui/button'
import { Typography } from '@/components/ui/typography'
import { QrCodeCard } from '@/components/settings/QrCodeCard'
import { SocialShareCard } from '@/components/settings/SocialShareCard'
import { toast } from 'sonner'
import { cn } from '@/lib/utils'
import {
  Copy,
  ExternalLink,
  ChevronDown,
  ChevronRight,
  Zap,
  Users,
  Layers,
  QrCode,
  X,
} from 'lucide-react'
import type { StudioBookingUrls, ArtistLinkInfo } from '@/lib/booking-links/urls'

interface BookingLinksResponse {
  data: StudioBookingUrls & {
    brandColor?: string | null
    studioName?: string
  }
}

// ── Helper: copy URL to clipboard ──────────────────────────────────────────
function useCopyUrl() {
  return useCallback(async (url: string, label = 'Link') => {
    try {
      await navigator.clipboard.writeText(url)
      toast.success(`${label} copied to clipboard`)
    } catch {
      toast.error('Copy failed — check browser permissions')
    }
  }, [])
}

// ── Collapsed / expandable section wrapper ─────────────────────────────────
function Section({
  title,
  icon,
  count,
  defaultOpen = true,
  children,
}: {
  title: string
  icon: React.ReactNode
  count?: number
  defaultOpen?: boolean
  children: React.ReactNode
}) {
  const [open, setOpen] = useState(defaultOpen)
  return (
    <div className="rounded-xl border border-border/60 overflow-hidden">
      <button
        type="button"
        className="w-full flex items-center justify-between px-4 py-3 bg-muted/20 hover:bg-muted/40 transition-colors"
        onClick={() => setOpen((o) => !o)}
        aria-expanded={open}
      >
        <div className="flex items-center gap-2">
          <span className="text-muted-foreground">{icon}</span>
          <span className="text-sm font-medium">{title}</span>
          {count !== undefined && (
            <span className="text-xs text-muted-foreground bg-muted px-1.5 py-0.5 rounded-full">
              {count}
            </span>
          )}
        </div>
        {open ? (
          <ChevronDown className="h-4 w-4 text-muted-foreground" />
        ) : (
          <ChevronRight className="h-4 w-4 text-muted-foreground" />
        )}
      </button>
      {open && <div className="p-4">{children}</div>}
    </div>
  )
}

// ── URL row: label + url + copy button ─────────────────────────────────────
function UrlRow({
  label,
  url,
  onCopy,
  onOpenQr,
}: {
  label: string
  url: string
  onCopy: () => void
  onOpenQr?: () => void
}) {
  return (
    <div className="flex items-center gap-2 py-2 border-b border-border/30 last:border-0">
      <div className="flex-1 min-w-0">
        <p className="text-xs font-medium truncate">{label}</p>
        <p className="text-xs text-muted-foreground truncate font-mono">{url}</p>
      </div>
      <div className="flex items-center gap-1 shrink-0">
        {onOpenQr && (
          <button
            type="button"
            onClick={onOpenQr}
            className="h-7 w-7 flex items-center justify-center rounded border border-border/60 text-muted-foreground hover:text-foreground hover:bg-muted/50 transition-colors"
            aria-label={`QR code for ${label}`}
          >
            <QrCode className="h-3.5 w-3.5" />
          </button>
        )}
        <button
          type="button"
          onClick={onCopy}
          className="h-7 w-7 flex items-center justify-center rounded border border-border/60 text-muted-foreground hover:text-foreground hover:bg-muted/50 transition-colors"
          aria-label={`Copy link for ${label}`}
        >
          <Copy className="h-3.5 w-3.5" />
        </button>
      </div>
    </div>
  )
}

// ── Artist row with avatar ──────────────────────────────────────────────────
function ArtistRow({
  artist,
  onCopy,
  onOpenQr,
}: {
  artist: ArtistLinkInfo
  onCopy: () => void
  onOpenQr: () => void
}) {
  return (
    <div className="flex items-center gap-3 py-2 border-b border-border/30 last:border-0">
      {/* Avatar */}
      <div className="h-8 w-8 rounded-full bg-muted border border-border/40 overflow-hidden shrink-0">
        {artist.avatarUrl ? (
          // eslint-disable-next-line @next/next/no-img-element
          <img
            src={artist.avatarUrl}
            alt={artist.displayName}
            className="h-full w-full object-cover"
          />
        ) : (
          <div className="h-full w-full flex items-center justify-center text-xs font-semibold text-muted-foreground/60">
            {artist.displayName[0]?.toUpperCase()}
          </div>
        )}
      </div>

      {/* Name + URL */}
      <div className="flex-1 min-w-0">
        <p className="text-xs font-medium truncate">{artist.displayName}</p>
        <p className="text-xs text-muted-foreground truncate font-mono">{artist.url}</p>
      </div>

      {/* Actions */}
      <div className="flex items-center gap-1 shrink-0">
        <button
          type="button"
          onClick={onOpenQr}
          className="h-7 w-7 flex items-center justify-center rounded border border-border/60 text-muted-foreground hover:text-foreground hover:bg-muted/50 transition-colors"
          aria-label={`QR code for ${artist.displayName}`}
        >
          <QrCode className="h-3.5 w-3.5" />
        </button>
        <button
          type="button"
          onClick={onCopy}
          className="h-7 w-7 flex items-center justify-center rounded border border-border/60 text-muted-foreground hover:text-foreground hover:bg-muted/50 transition-colors"
          aria-label={`Copy link for ${artist.displayName}`}
        >
          <Copy className="h-3.5 w-3.5" />
        </button>
      </div>
    </div>
  )
}

// ── QR overlay modal ────────────────────────────────────────────────────────
function QrModal({
  url,
  label,
  brandColor,
  onClose,
}: {
  url: string
  label: string
  brandColor?: string | null
  onClose: () => void
}) {
  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4"
      onClick={onClose}
    >
      <div
        className="relative bg-background rounded-2xl border border-border shadow-card w-full max-w-sm p-6 space-y-4"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center justify-between">
          <p className="text-sm font-semibold">QR code — {label}</p>
          <Button
            variant="ghost"
            size="icon"
            className="h-7 w-7"
            onClick={onClose}
            aria-label="Close QR modal"
          >
            <X className="h-4 w-4" />
          </Button>
        </div>
        <QrCodeCard url={url} brandColor={brandColor} />
        <p className="text-xs text-muted-foreground text-center font-mono break-all">{url}</p>
      </div>
    </div>
  )
}

// ── Main hub component ──────────────────────────────────────────────────────
export function BookingLinkHub() {
  const copyUrl = useCopyUrl()
  const [qrTarget, setQrTarget] = useState<{ url: string; label: string } | null>(null)
  const [previewOpen, setPreviewOpen] = useState(false)

  const { data, isLoading, error } = useQuery<BookingLinksResponse>({
    queryKey: ['booking-links'],
    queryFn: async () => {
      const res = await fetch('/api/booking-links')
      if (!res.ok) throw new Error('Failed to load booking links')
      return res.json() as Promise<BookingLinksResponse>
    },
  })

  const urls = data?.data
  const brandColor = urls?.brandColor ?? null
  const studioName = urls?.studioName

  if (isLoading) {
    return (
      <div className="space-y-4 p-6 max-w-3xl">
        <Skeleton className="h-32 w-full rounded-xl" />
        <Skeleton className="h-48 w-full rounded-xl" />
        <Skeleton className="h-32 w-full rounded-xl" />
      </div>
    )
  }

  if (error || !urls) {
    return (
      <div className="p-6 text-sm text-muted-foreground">
        Failed to load booking links. Refresh the page.
      </div>
    )
  }

  return (
    <>
      <div className="space-y-4 p-6 max-w-3xl">
        {/* Hero card — studio booking URL */}
        <div className="rounded-xl border border-border/60 bg-card p-5 space-y-4">
          <div>
            <Typography variant="h3" as="h2" className="text-sm">
              Your booking link
            </Typography>
            <p className="text-xs text-muted-foreground mt-0.5">
              Share anywhere — Instagram bio, stories, DMs, your website.
            </p>
          </div>

          {/* URL display */}
          <div className="flex items-center gap-2 rounded-lg border border-border/60 bg-muted/30 px-3 py-2.5">
            <span className="flex-1 text-sm font-mono truncate text-foreground">
              {urls.studioUrl}
            </span>
            <div className="flex items-center gap-1 shrink-0">
              <button
                type="button"
                onClick={() => void copyUrl(urls.studioUrl, 'Booking link')}
                className="h-7 w-7 flex items-center justify-center rounded border border-border/60 text-muted-foreground hover:text-foreground hover:bg-muted/50 transition-colors"
                aria-label="Copy booking link"
              >
                <Copy className="h-3.5 w-3.5" />
              </button>
              <a
                href={urls.studioUrl}
                target="_blank"
                rel="noopener noreferrer"
                className="h-7 w-7 flex items-center justify-center rounded border border-border/60 text-muted-foreground hover:text-foreground hover:bg-muted/50 transition-colors"
                aria-label="Open booking page in new tab"
              >
                <ExternalLink className="h-3.5 w-3.5" />
              </a>
            </div>
          </div>

          {/* CTA row */}
          <div className="flex flex-wrap gap-2">
            <Button
              variant="outline"
              size="sm"
              className="h-8 text-xs gap-1.5"
              onClick={() => setQrTarget({ url: urls.studioUrl, label: 'Studio booking page' })}
            >
              <QrCode className="h-3.5 w-3.5" />
              Get QR code
            </Button>
            <Button
              variant="outline"
              size="sm"
              className="h-8 text-xs gap-1.5"
              onClick={() => setPreviewOpen(true)}
            >
              <ExternalLink className="h-3.5 w-3.5" />
              Preview on mobile
            </Button>
          </div>
        </div>

        {/* Per-artist links */}
        {urls.artistLinks.length > 0 && (
          <Section
            title="Artist booking links"
            icon={<Users className="h-4 w-4" />}
            count={urls.artistLinks.length}
          >
            <div>
              {urls.artistLinks.map((artist) => (
                <ArtistRow
                  key={artist.id}
                  artist={artist}
                  onCopy={() => void copyUrl(artist.url, `${artist.displayName}'s link`)}
                  onOpenQr={() => setQrTarget({ url: artist.url, label: artist.displayName })}
                />
              ))}
            </div>
          </Section>
        )}

        {/* Per-service links */}
        {urls.serviceLinks.length > 0 && (
          <Section
            title="Service booking links"
            icon={<Layers className="h-4 w-4" />}
            count={urls.serviceLinks.length}
            defaultOpen={false}
          >
            <div>
              {urls.serviceLinks.map((service) => (
                <UrlRow
                  key={service.id}
                  label={service.name}
                  url={service.url}
                  onCopy={() => void copyUrl(service.url, `${service.name} link`)}
                  onOpenQr={() => setQrTarget({ url: service.url, label: service.name })}
                />
              ))}
            </div>
          </Section>
        )}

        {/* Flash event links */}
        {urls.flashEventLinks.length > 0 && (
          <Section
            title="Flash event links"
            icon={<Zap className="h-4 w-4" />}
            count={urls.flashEventLinks.length}
            defaultOpen={false}
          >
            <div>
              {urls.flashEventLinks.map((event) => (
                <UrlRow
                  key={event.id}
                  label={`${event.title} — ${new Date(event.eventDate).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}`}
                  url={event.url}
                  onCopy={() => void copyUrl(event.url, `${event.title} link`)}
                />
              ))}
            </div>
          </Section>
        )}

        {/* Bottom row: QR generator + Social share */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <QrCodeCard url={urls.studioUrl} label="Studio QR code" brandColor={brandColor} />
          <SocialShareCard url={urls.studioUrl} studioName={studioName} />
        </div>
      </div>

      {/* QR modal */}
      {qrTarget && (
        <QrModal
          url={qrTarget.url}
          label={qrTarget.label}
          brandColor={brandColor}
          onClose={() => setQrTarget(null)}
        />
      )}

      {/* Mobile preview modal */}
      {previewOpen && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4"
          onClick={() => setPreviewOpen(false)}
        >
          <div
            className="relative bg-background rounded-2xl border border-border shadow-card flex flex-col overflow-hidden"
            style={{ width: 390, height: 680 }}
            onClick={(e) => e.stopPropagation()}
          >
            {/* Phone notch decoration */}
            <div className="flex items-center justify-between px-4 py-2 border-b border-border/40 bg-muted/20">
              <div className="w-16 h-1.5 rounded-full bg-border/60 mx-auto" />
              <Button
                variant="ghost"
                size="icon"
                className="h-6 w-6 absolute right-3"
                onClick={() => setPreviewOpen(false)}
                aria-label="Close preview"
              >
                <X className="h-3.5 w-3.5" />
              </Button>
            </div>

            {/* iframe booking preview */}
            <iframe
              src={urls.studioUrl}
              className="flex-1 w-full"
              title="Booking page preview"
              sandbox="allow-scripts allow-same-origin allow-forms"
            />
          </div>
        </div>
      )}
    </>
  )
}

