/**
 * /book/[studioSlug]/service/[serviceId]
 *
 * Canonical per-service direct booking URL surfaced in the Booking Link Hub.
 * Redirects to the existing booking flow at /book/[studioSlug]/[serviceId]
 * so we avoid duplicating the full booking page component.
 */
import { redirect } from 'next/navigation'

interface Props {
  params: Promise<{ studioSlug: string; serviceId: string }>
}

export default async function ServiceBookingRedirectPage({ params }: Props) {
  const { studioSlug, serviceId } = await params
  redirect(`/book/${studioSlug}/${serviceId}`)
}

'use client'

/**
 * /book/[studioSlug]/artist/[artistSlug]
 *
 * Per-artist direct booking page.
 * Resolves the artist by (studio_slug, artist_slug) then renders the studio
 * booking flow pre-filtered to that artist.
 *
 * Reuses the same API endpoints as the studio booking root; the artistId is
 * passed as a URL param when navigating into the service booking step.
 */
import { use } from 'react'
import { useQuery } from '@tanstack/react-query'
import { Skeleton } from '@/components/ui/skeleton'
import { Typography } from '@/components/ui/typography'
import { useRouter } from 'next/navigation'
import { formatCurrency } from '@/lib/utils'
import { TrustBadges } from '@/components/booking/TrustBadges'
import { Clock, ChevronRight, ArrowLeft } from 'lucide-react'

interface StudioPublic {
  id: string
  name: string
  slug: string
  brand_color: string | null
  logo_url: string | null
  show_prices?: boolean
}

interface ArtistPublic {
  id: string
  display_name: string
  avatar_url: string | null
  bio: string | null
  specialties: string[]
  profile_bio_public: string | null
  social_instagram: string | null
}

interface ServicePublic {
  id: string
  name: string
  description: string | null
  duration_min: number
  base_price_cents: number
  deposit_cents: number
  deposit_required: boolean
  color: string | null
}

export default function ArtistBookingPage({
  params,
}: {
  params: Promise<{ studioSlug: string; artistSlug: string }>
}) {
  const { studioSlug, artistSlug } = use(params)
  const router = useRouter()

  const { data: studioData, isLoading: studioLoading, error: studioError } = useQuery<{ data: StudioPublic }>({
    queryKey: ['public', 'studio', studioSlug],
    queryFn: async () => {
      const res = await fetch(`/api/public/studios/${studioSlug}`)
      if (!res.ok) throw new Error('Studio not found')
      return res.json() as Promise<{ data: StudioPublic }>
    },
  })

  const studio = studioData?.data

  const { data: artistData, isLoading: artistLoading, error: artistError } = useQuery<{ data: ArtistPublic | null }>({
    queryKey: ['public', 'artist-by-slug', studioSlug, artistSlug],
    queryFn: async () => {
      const res = await fetch(`/api/public/studios/${studioSlug}/artists/${artistSlug}`)
      if (res.status === 404) return { data: null }
      if (!res.ok) throw new Error('Failed to load artist')
      return res.json() as Promise<{ data: ArtistPublic }>
    },
    enabled: !!studio,
  })

  const artist = artistData?.data

  const { data: servicesData, isLoading: servicesLoading } = useQuery<{ data: ServicePublic[] }>({
    queryKey: ['public', 'artist-services', studioSlug, artist?.id],
    queryFn: async () => {
      const res = await fetch(
        `/api/public/studios/${studioSlug}/services?artistId=${artist!.id}`
      )
      if (!res.ok) throw new Error('Failed to load services')
      return res.json() as Promise<{ data: ServicePublic[] }>
    },
    enabled: !!artist?.id,
  })

  const brandColor = studio?.brand_color ?? null
  const services = servicesData?.data ?? []

  if (studioError) {
    return (
      <div className="min-h-svh flex items-center justify-center p-6">
        <div className="text-center space-y-3">
          <p className="text-lg font-semibold">Studio not found</p>
          <p className="text-sm text-muted-foreground">
            The booking page you&apos;re looking for doesn&apos;t exist.
          </p>
        </div>
      </div>
    )
  }

  if (!artistLoading && (artistError || artist === null)) {
    return (
      <div className="min-h-svh flex items-center justify-center p-6">
        <div className="text-center space-y-3">
          <p className="text-lg font-semibold">Artist not found</p>
          <p className="text-sm text-muted-foreground">
            This artist&apos;s booking page isn&apos;t available.
          </p>
          <button
            type="button"
            className="text-sm underline text-muted-foreground mt-2"
            onClick={() => router.push(`/book/${studioSlug}`)}
          >
            View all artists
          </button>
        </div>
      </div>
    )
  }

  return (
    <div
      className="min-h-svh"
      style={brandColor ? ({ '--booking-brand': brandColor } as React.CSSProperties) : undefined}
    >
      {/* Hero / header */}
      {studioLoading ? (
        <div className="h-40 bg-muted animate-pulse" />
      ) : (
        <div
          className="relative"
          style={
            brandColor
              ? { background: `linear-gradient(135deg, ${brandColor}20, ${brandColor}08)` }
              : undefined
          }
        >
          <div className="max-w-2xl mx-auto px-4 py-8">
            <button
              type="button"
              className="flex items-center gap-1.5 text-xs text-muted-foreground hover:text-foreground mb-4 transition-colors"
              onClick={() => router.push(`/book/${studioSlug}`)}
            >
              <ArrowLeft className="h-3.5 w-3.5" />
              All artists
            </button>

            {/* Artist profile */}
            {artistLoading ? (
              <div className="flex items-center gap-4">
                <Skeleton className="h-16 w-16 rounded-full" />
                <div className="space-y-2">
                  <Skeleton className="h-6 w-40" />
                  <Skeleton className="h-4 w-56" />
                </div>
              </div>
            ) : artist ? (
              <div className="flex items-start gap-4">
                <div className="h-16 w-16 rounded-full bg-muted border border-border/40 overflow-hidden shrink-0">
                  {artist.avatar_url ? (
                    // eslint-disable-next-line @next/next/no-img-element
                    <img
                      src={artist.avatar_url}
                      alt={artist.display_name}
                      className="h-full w-full object-cover"
                    />
                  ) : (
                    <div className="h-full w-full flex items-center justify-center text-2xl font-semibold text-muted-foreground/40">
                      {artist.display_name[0]?.toUpperCase()}
                    </div>
                  )}
                </div>
                <div className="min-w-0">
                  {/* raw-heading: public booking page artist name — display-level heading per brand spec */}
                  <Typography variant="h1" as="h1">
                    {artist.display_name}
                  </Typography>
                  {artist.specialties.length > 0 && (
                    <p className="text-sm text-muted-foreground mt-0.5">
                      {artist.specialties.slice(0, 3).join(' · ')}
                    </p>
                  )}
                  {(artist.profile_bio_public ?? artist.bio) && (
                    <p className="text-sm text-muted-foreground/80 mt-2 max-w-md line-clamp-3">
                      {artist.profile_bio_public ?? artist.bio}
                    </p>
                  )}
                  {artist.social_instagram && (
                    <a
                      href={`https://instagram.com/${artist.social_instagram.replace('@', '')}`}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="text-xs text-muted-foreground underline mt-1 inline-block"
                    >
                      @{artist.social_instagram.replace('@', '')}
                    </a>
                  )}
                </div>
              </div>
            ) : null}

            {studio && (
              <p className="text-xs text-muted-foreground mt-3">
                at {studio.name}
              </p>
            )}
          </div>
        </div>
      )}

      {/* Trust badges */}
      <div className="border-y border-border/30 bg-muted/20 py-3">
        <TrustBadges className="max-w-2xl mx-auto px-4" />
      </div>

      {/* Services */}
      <div className="max-w-2xl mx-auto px-4 py-8">
        <section className="space-y-3">
          <Typography variant="h2">Choose a service</Typography>

          {servicesLoading || artistLoading ? (
            <div className="space-y-2">
              {Array.from({ length: 3 }).map((_, i) => (
                <Skeleton key={i} className="h-16 w-full rounded-xl" />
              ))}
            </div>
          ) : services.length === 0 ? (
            <p className="text-sm text-muted-foreground">
              No services available for this artist.
            </p>
          ) : (
            <div className="space-y-2">
              {services.map((service) => (
                <button
                  key={service.id}
                  className="booking-service-card w-full flex items-center justify-between"
                  onClick={() =>
                    router.push(
                      `/book/${studioSlug}/${service.id}?artistId=${artist?.id ?? ''}`
                    )
                  }
                >
                  <div className="flex items-center gap-3 min-w-0">
                    {service.color && (
                      <span
                        className="h-3 w-3 rounded-full shrink-0"
                        style={{ backgroundColor: service.color }}
                      />
                    )}
                    <div className="min-w-0 text-left">
                      <p className="text-sm font-medium">{service.name}</p>
                      {service.description && (
                        <p className="text-xs text-muted-foreground truncate max-w-[280px]">
                          {service.description}
                        </p>
                      )}
                      <p className="text-xs text-muted-foreground flex items-center gap-1 mt-0.5">
                        <Clock className="h-3 w-3" />
                        {service.duration_min} min
                        {studio?.show_prices !== false && (
                          <> · {formatCurrency(service.base_price_cents)}</>
                        )}
                      </p>
                    </div>
                  </div>
                  <ChevronRight className="h-4 w-4 text-muted-foreground shrink-0" />
                </button>
              ))}
            </div>
          )}
        </section>
      </div>
    </div>
  )
}

/**
 * GET /api/public/studios/[slug]/artists/[artistSlug]
 *
 * Returns a single active artist for a studio resolved by display_name slug.
 * Slug matching is case-insensitive and tolerates minor normalization diffs.
 *
 * Returns 404 if studio not found, artist not found, or artist not active.
 */
import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { createPublicClient } from '@/lib/supabase/public'
import { publicBookingReadRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { slugify } from '@/lib/utils'
import { logger } from '@/lib/logger'

interface Params {
  params: Promise<{ slug: string; artistSlug: string }>
}

export async function GET(request: NextRequest, { params }: Params) {
  const ip = getClientIp(request)
  const { success } = await publicBookingReadRatelimit.limit(ip)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { slug, artistSlug } = await params

  if (!z.string().min(1).max(100).safeParse(slug).success) {
    return NextResponse.json({ error: 'Invalid slug' }, { status: 400 })
  }
  if (!z.string().min(1).max(200).safeParse(artistSlug).success) {
    return NextResponse.json({ error: 'Invalid artist slug' }, { status: 400 })
  }

  try {
    const supabase = createPublicClient()

    // Resolve studio
    const { data: studio, error: studioError } = await supabase
      .rpc('public_get_studio_by_slug', { p_slug: slug })

    if (studioError || !studio) {
      return NextResponse.json({ error: 'Studio not found' }, { status: 404 })
    }

    const studioObj = studio as { id: string }

    // Fetch all active artists for this studio then match by slug
    const { data: artists, error: artistsError } = await supabase
      .from('artists')
      .select(
        'id, display_name, avatar_url, bio, specialties, profile_bio_public, social_instagram, status'
      )
      .eq('studio_id', studioObj.id)
      .eq('status', 'active')

    if (artistsError) {
      logger.error({ err: artistsError, slug, artistSlug }, 'public artist-by-slug fetch failed')
      return NextResponse.json({ error: 'Failed to fetch artists' }, { status: 500 })
    }

    if (!artists || artists.length === 0) {
      return NextResponse.json({ error: 'Artist not found' }, { status: 404 })
    }

    // Match by slugified display_name (case-insensitive, normalized)
    const normalizedTarget = slugify(artistSlug)
    const matched = artists.find(
      (a) => slugify(a.display_name) === normalizedTarget
    )

    if (!matched) {
      return NextResponse.json({ error: 'Artist not found' }, { status: 404 })
    }

    const {
      id,
      display_name,
      avatar_url,
      bio,
      specialties,
      profile_bio_public,
      social_instagram,
    } = matched

    return NextResponse.json({
      data: {
        id,
        display_name,
        avatar_url,
        bio,
        specialties,
        profile_bio_public,
        social_instagram,
      },
    })
  } catch (err) {
    logger.error({ err, slug, artistSlug }, 'public artist-by-slug GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

