  if (!z.string().min(1).max(100).safeParse(slug).success) {
    return NextResponse.json({ error: 'Invalid slug' }, { status: 400 })
  }

  // Optional: filter services by artist when artistId query param is present
  const artistId = request.nextUrl.searchParams.get('artistId')
  const parsedArtistId = artistId && z.string().uuid().safeParse(artistId).success
    ? artistId
    : null

  try {
    const supabase = createPublicClient()

    // First resolve studio id from slug
    const { data: studio, error: studioError } = await supabase
      .rpc('public_get_studio_by_slug', { p_slug: slug })

    if (studioError || !studio) {
      return NextResponse.json({ error: 'Studio not found' }, { status: 404 })
    }

    const studioObj = studio as { id: string }

    // When artistId provided: return only services linked to that artist via service_artists
    if (parsedArtistId) {
      const { data: serviceIds, error: linkError } = await supabase
        .from('service_artists')
        .select('service_id')
        .eq('artist_id', parsedArtistId)

      if (linkError) {
        logger.error({ err: linkError, slug, artistId: parsedArtistId }, 'artist service-links fetch failed')
        return NextResponse.json({ error: 'Failed to fetch services' }, { status: 500 })
      }

      if (!serviceIds || serviceIds.length === 0) {
        // Artist exists but has no linked services — fall through to all services
      } else {
        const ids = serviceIds.map((row) => row.service_id)
        const { data: allServices, error: servicesError } = await supabase
          .rpc('public_get_services_for_studio', { p_studio_id: studioObj.id })

        if (servicesError) {
          logger.error({ err: servicesError, slug }, 'public services fetch failed')
          return NextResponse.json({ error: 'Failed to fetch services' }, { status: 500 })
        }

        const filtered = (allServices ?? []).filter(
          (s: { id: string }) => ids.includes(s.id)
        )
        return NextResponse.json({ data: filtered })
      }
    }

    const { data, error } = await supabase
      .rpc('public_get_services_for_studio', { p_studio_id: studioObj.id })

    if (error) {
      logger.error({ err: error, slug }, 'public services fetch failed')
      return NextResponse.json({ error: 'Failed to fetch services' }, { status: 500 })
